<?php namespace App\Http\Controllers;
use App\Models\Tourism; use Illuminate\Http\Request;
class TourismController extends Controller { public function index(){return view('tourism.index',['destinations'=>Tourism::latest()->paginate(15)]);} public function create(){return view('tourism.form',['destination'=>new Tourism]);} public function store(Request $r){Tourism::create($r->validate(['name'=>'required','description'=>'nullable','latitude'=>'required|numeric','longitude'=>'required|numeric','address'=>'nullable','ticket_price'=>'nullable|numeric','opening_time'=>'nullable','closing_time'=>'nullable','status'=>'required']));return redirect()->route('tourism.index');} public function show(Tourism $tourism){$destination=$tourism;return view('tourism.show',compact('destination'));} public function edit(Tourism $tourism){$destination=$tourism;return view('tourism.form',compact('destination'));} public function update(Request $r,Tourism $tourism){$tourism->update($r->all());return redirect()->route('tourism.index');} public function destroy(Tourism $tourism){$tourism->delete();return back();} }
